import './offline-store.js';
const db=globalThis.MeteoOffline;
const key=p=>`${Math.round(p.latitude*100)/100},${Math.round(p.longitude*100)/100}`;
export async function savedWeather(place){try{const row=await db.get('weather',key(place));return row&&row.data?._loadedAt<=Date.now()&&Date.now()-row.data._loadedAt<7*86400000?{...row.data,_offline:true}:null}catch{return null}}
export async function saveWeather(place,data){try{await db.put('weather',{id:key(place),data})}catch{}}
async function schedule(){try{const reg=await navigator.serviceWorker.getRegistration();await reg?.sync?.register('sky-outbox')}catch{}}
export async function sendObservation(payload){payload={...payload,observedAt:payload.observedAt||Date.now(),latitude:Math.round(payload.latitude*100)/100,longitude:Math.round(payload.longitude*100)/100};let owner;
 try{owner=(await db.get('meta','actor'))?.value}catch{}
 try{const session=await db.request('session',{});owner=session.actor;try{await db.put('meta',{id:'actor',value:owner})}catch{};const result=await db.request('reports',{...payload,expectedActor:owner});window.dispatchEvent(new Event('sky-published'));return result}
 catch(e){if(e.status&&e.status<500&&e.status!==429)throw e;try{const rows=await db.all('outbox');if(rows.length>=10&&!rows.some(r=>r.id===payload.id))throw Error('La coda contiene già 10 segnalazioni.');await db.put('outbox',{id:payload.id,payload,owner:owner||null,blocked:false});await schedule();await paint();return {queued:true}}catch{throw Error('Non riesco a salvare la segnalazione sul dispositivo. Riprova senza chiudere la pagina.')}}
}
async function paint(){let rows,result;try{rows=await db.all('outbox');result=await db.get('meta','result')}catch{return}let host=document.querySelector('#offline-outbox');if(!host){host=document.createElement('aside');host.id='offline-outbox';host.className='sky-success';host.setAttribute('aria-live','polite');document.querySelector('#main')?.before(host)}host.replaceChildren();for(const row of rows){const line=document.createElement('p');line.textContent=`${row.payload.city} · ${row.payload.phenomenon||'Osservazione'}: ${row.message||(row.owner?'Verrà inviata appena torni online, entro 2 ore.':'Salvata sul dispositivo. Quando torna la rete, premi Riprova invio per iniziare la sessione.')}`;host.append(line);const retry=document.createElement('button');retry.textContent='Riprova invio';retry.onclick=async()=>{retry.disabled=true;try{const session=await db.request('session',{});if(row.owner&&row.owner!==session.actor)throw Error('Riapri la sessione originale per inviare questa segnalazione.');await db.put('outbox',{...row,owner:session.actor,blocked:false,message:''});await db.flush();window.dispatchEvent(new Event('sky-published'))}catch(e){line.textContent=e.message}finally{retry.disabled=false;await paint()}};const cancel=document.createElement('button');cancel.textContent='Elimina dalla coda';cancel.onclick=async()=>{await db.remove('outbox',row.id);await paint()};host.append(retry,cancel)}if(result){const line=document.createElement('p');line.textContent=result.text;host.append(line);const dismiss=document.createElement('button');dismiss.textContent='Chiudi avviso';dismiss.onclick=async()=>{await db.remove('meta','result');paint()};host.append(dismiss)}host.hidden=!host.childNodes.length}
export function installOffline(){const retry=async()=>{try{await db.flush()}catch{await schedule()}await paint()};window.addEventListener('online',retry);navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='SKY_SYNC_DONE'){paint();window.dispatchEvent(new Event('sky-published'))}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)retry()});retry()}
